using SchematicBuilderMC.Builder;
using SchematicBuilderMC.Enums;
using SchematicBuilderMC.Extensions;
using SchematicBuilderMC.Models;
using SchematicBuilderMC.Registries;
using SchematicBuilderMC.Schematics.Redstone.Internal;

namespace SchematicBuilderMC.Schematics.Redstone.Pulse;

/// <summary>
/// Supported monostable pulse-limiting topologies.
/// </summary>
public enum PulseGeneratorMode
{
    /// <summary>1-wide piston monostable cutting input after 1-4 redstone ticks (2-8 gt).</summary>
    StickyPistonMonostable,

    /// <summary>2-gt pulse generated by an observer watching input state changes, stretched via optional repeater.</summary>
    ObserverMonostable,

    /// <summary>Silent solid-state comparator subtraction pulse limiter producing a configurable 2-8 gt pulse.</summary>
    RepeaterCutoffLimiter
}

/// <summary>
/// Builds a Redstone pulse generator / monostable pulse limiter that turns a sustained signal into a short pulse.
/// Supports optional <see cref="PulseDuration"/> or <see cref="PulseDurationTicks"/> (2-8 game ticks).
/// </summary>
public class PulseGeneratorSchematicCreator : SchematicCreator
{
    public PulseGeneratorMode Mode { get; set; } = PulseGeneratorMode.StickyPistonMonostable;

    /// <summary>
    /// Optional target output pulse duration (clamped to 2-8 game ticks).
    /// </summary>
    public TimeSpan? PulseDuration { get; set; }

    /// <summary>
    /// Optional target output pulse duration in game ticks (2-8 gt; overrides <see cref="PulseDuration"/>).
    /// </summary>
    public int? PulseDurationTicks { get; set; }

    public Direction Facing { get; set; } = Direction.East;

    public string CircuitBlock { get; set; } = Minecraft.Blocks.SmoothStone;

    public bool IncludeInputLever { get; set; }

    public bool IncludeOutputLamp { get; set; }

    public int GetActualPulseTicks()
    {
        int raw = CircuitLayout.ResolveGameTicks(PulseDuration, PulseDurationTicks, defaultGameTicks: 2, minGameTicks: 2, stepGameTicks: 2);
        return Math.Clamp(raw, 2, 8);
    }

    public override SchematicBuilder Create()
    {
        if (!Enum.IsDefined(Mode))
        {
            throw new ArgumentOutOfRangeException(nameof(Mode), Mode, "Unsupported pulse generator mode.");
        }

        CircuitLayout.ValidateHorizontalFacing(Facing);
        CircuitLayout.ValidateBlockId(CircuitBlock, nameof(CircuitBlock));
        int pulseTicks = GetActualPulseTicks();
        int repeaterDelay = pulseTicks / 2;

        return Mode switch
        {
            PulseGeneratorMode.StickyPistonMonostable => BuildPistonMonostable(repeaterDelay, pulseTicks),
            PulseGeneratorMode.ObserverMonostable => BuildObserverMonostable(repeaterDelay, pulseTicks),
            PulseGeneratorMode.RepeaterCutoffLimiter => BuildComparatorLimiter(repeaterDelay, pulseTicks),
            _ => throw new ArgumentOutOfRangeException(nameof(Mode), Mode, "Unsupported pulse generator mode.")
        };
    }

    private SchematicBuilder BuildPistonMonostable(int repeaterDelay, int pulseTicks)
    {
        int inputLead = IncludeInputLever ? 1 : 0;
        int coreLengthU = 5;
        int totalLengthU = inputLead + coreLengthU + (IncludeOutputLamp ? 1 : 0);
        int height = IncludeInputLever ? 3 : 3;
        int maxU = totalLengthU - 1;

        var builder = CircuitLayout.CreateBuilder(
            this,
            CircuitLayout.GetWidth(totalLengthU, 1, Facing),
            height,
            CircuitLayout.GetLength(totalLengthU, 1, Facing),
            "Piston Monostable Pulse Generator",
            $"1-wide sticky piston pulse limiter ({pulseTicks} gt pulse) facing {Facing}.");

        for (int u = 0; u < totalLengthU; u++)
        {
            if (u == inputLead + 2)
            {
                continue;
            }

            builder.SetBlock(CircuitLayout.Map(0, 0, 0, u, 0, 0, maxU, 0, Facing), CircuitBlock);
        }

        if (IncludeInputLever)
        {
            builder.SetBlock(CircuitLayout.Map(0, 0, 0, 0, 1, 0, maxU, 0, Facing), CircuitBlock);
            builder.SetLever(CircuitLayout.Map(0, 0, 0, 0, 2, 0, maxU, 0, Facing), BlockFace.Floor, Facing, powered: false);
        }

        builder.SetBlock(CircuitLayout.Map(0, 0, 0, inputLead, 1, 0, maxU, 0, Facing), CircuitLayout.CreateAxisWire(Facing, true));
        CircuitLayout.SetRepeater(builder, CircuitLayout.Map(0, 0, 0, inputLead + 1, 1, 0, maxU, 0, Facing), Facing, delay: 1);
        builder.SetPiston(CircuitLayout.Map(0, 0, 0, inputLead + 2, 0, 0, maxU, 0, Facing), Direction.Up, sticky: true);
        builder.SetBlock(CircuitLayout.Map(0, 0, 0, inputLead + 2, 1, 0, maxU, 0, Facing), CircuitBlock);
        CircuitLayout.SetRepeater(builder, CircuitLayout.Map(0, 0, 0, inputLead + 3, 1, 0, maxU, 0, Facing), Facing, delay: repeaterDelay);
        builder.SetBlock(CircuitLayout.Map(0, 0, 0, inputLead + 4, 1, 0, maxU, 0, Facing), CircuitLayout.CreateAxisWire(Facing, true));

        if (IncludeOutputLamp)
        {
            builder.SetBlock(CircuitLayout.Map(0, 0, 0, totalLengthU - 1, 1, 0, maxU, 0, Facing), Minecraft.Blocks.RedstoneLamp);
        }

        return builder;
    }

    private SchematicBuilder BuildObserverMonostable(int repeaterDelay, int pulseTicks)
    {
        int inputLead = IncludeInputLever ? 1 : 0;
        int coreLengthU = 4;
        int totalLengthU = inputLead + coreLengthU + (IncludeOutputLamp ? 1 : 0);
        int height = IncludeInputLever ? 3 : 2;
        int maxU = totalLengthU - 1;

        var builder = CircuitLayout.CreateBuilder(
            this,
            CircuitLayout.GetWidth(totalLengthU, 1, Facing),
            height,
            CircuitLayout.GetLength(totalLengthU, 1, Facing),
            "Observer Monostable",
            $"Observer pulse generator ({pulseTicks} gt reshaped output) facing {Facing}.");

        for (int u = 0; u < totalLengthU; u++)
        {
            builder.SetBlock(CircuitLayout.Map(0, 0, 0, u, 0, 0, maxU, 0, Facing), CircuitBlock);
        }

        if (IncludeInputLever)
        {
            builder.SetBlock(CircuitLayout.Map(0, 0, 0, 0, 1, 0, maxU, 0, Facing), CircuitBlock);
            builder.SetLever(CircuitLayout.Map(0, 0, 0, 0, 2, 0, maxU, 0, Facing), BlockFace.Floor, Facing, powered: false);
        }

        builder.SetBlock(CircuitLayout.Map(0, 0, 0, inputLead, 1, 0, maxU, 0, Facing), CircuitLayout.CreateAxisWire(Facing, true));
        CircuitLayout.SetObserver(
            builder,
            CircuitLayout.Map(0, 0, 0, inputLead + 1, 1, 0, maxU, 0, Facing),
            CircuitLayout.RotateDirection(Direction.West, Facing));
        CircuitLayout.SetRepeater(builder, CircuitLayout.Map(0, 0, 0, inputLead + 2, 1, 0, maxU, 0, Facing), Facing, delay: repeaterDelay);
        builder.SetBlock(CircuitLayout.Map(0, 0, 0, inputLead + 3, 1, 0, maxU, 0, Facing), CircuitLayout.CreateAxisWire(Facing, true));

        if (IncludeOutputLamp)
        {
            builder.SetBlock(CircuitLayout.Map(0, 0, 0, totalLengthU - 1, 1, 0, maxU, 0, Facing), Minecraft.Blocks.RedstoneLamp);
        }

        return builder;
    }

    private SchematicBuilder BuildComparatorLimiter(int repeaterDelay, int pulseTicks)
    {
        int inputLead = IncludeInputLever ? 1 : 0;
        int coreLengthU = 4;
        const int widthV = 2;
        int totalLengthU = inputLead + coreLengthU + (IncludeOutputLamp ? 1 : 0);
        int height = IncludeInputLever ? 3 : 2;
        int maxU = totalLengthU - 1;
        int maxV = widthV - 1;

        var builder = CircuitLayout.CreateBuilder(
            this,
            CircuitLayout.GetWidth(totalLengthU, widthV, Facing),
            height,
            CircuitLayout.GetLength(totalLengthU, widthV, Facing),
            "Comparator Subtraction Pulse Limiter",
            $"Silent solid-state pulse limiter ({pulseTicks} gt pulse) facing {Facing}.");

        for (int u = 0; u < totalLengthU; u++)
        {
            for (int v = 0; v < widthV; v++)
            {
                builder.SetBlock(CircuitLayout.Map(0, 0, 0, u, 0, v, maxU, maxV, Facing), CircuitBlock);
            }
        }

        if (IncludeInputLever)
        {
            builder.SetBlock(CircuitLayout.Map(0, 0, 0, 0, 1, 0, maxU, maxV, Facing), CircuitBlock);
            builder.SetLever(CircuitLayout.Map(0, 0, 0, 0, 2, 0, maxU, maxV, Facing), BlockFace.Floor, Facing, powered: false);
        }

        builder.SetBlock(CircuitLayout.Map(0, 0, 0, inputLead, 1, 0, maxU, maxV, Facing), CircuitLayout.CreateWire(Facing, north: false, east: true, south: true, west: true));
        builder.SetBlock(CircuitLayout.Map(0, 0, 0, inputLead, 1, 1, maxU, maxV, Facing), CircuitLayout.CreateWire(Facing, north: true, east: true, south: false, west: false));

        builder.SetBlock(CircuitLayout.Map(0, 0, 0, inputLead + 1, 1, 0, maxU, maxV, Facing), CircuitLayout.CreateAxisWire(Facing, true));
        CircuitLayout.SetRepeater(builder, CircuitLayout.Map(0, 0, 0, inputLead + 1, 1, 1, maxU, maxV, Facing), Facing, delay: repeaterDelay);

        CircuitLayout.SetComparator(builder, CircuitLayout.Map(0, 0, 0, inputLead + 2, 1, 0, maxU, maxV, Facing), Facing, subtractMode: true);
        builder.SetBlock(CircuitLayout.Map(0, 0, 0, inputLead + 2, 1, 1, maxU, maxV, Facing), CircuitLayout.CreateWire(Facing, north: true, east: false, south: false, west: true));

        builder.SetBlock(CircuitLayout.Map(0, 0, 0, inputLead + 3, 1, 0, maxU, maxV, Facing), CircuitLayout.CreateAxisWire(Facing, true));

        if (IncludeOutputLamp)
        {
            builder.SetBlock(CircuitLayout.Map(0, 0, 0, totalLengthU - 1, 1, 0, maxU, maxV, Facing), Minecraft.Blocks.RedstoneLamp);
        }

        return builder;
    }
}
